<script lang="ts">
  import { onDestroy, onMount, untrack, type Snippet } from 'svelte';
  import Icon from './Icon.svelte';
  import type { DeepReadonly, ProfileDocument, ProfileLocalAssignment } from './profiles';
  import type { ObservedResourcePort, ProfileInventoryClient, ResourceDetails, ResourceSummary } from './profile-inventory';
  import type { GameId } from './games';
  import { PROFILE_BLOCK_HEIGHT, PROFILE_BLOCK_WIDTH, profileAutoLayout } from './profile-editor';
  import { canvasFit, canvasGameId, canvasMove, canvasNodes, canvasPan, canvasSearch, canvasStatus, canvasTransports, canvasZoom, portContractLabel, type CanvasNode, type CanvasPoint, type CanvasViewport } from './profile-canvas';
  import {processingSummary} from './profile-processing';
  import type{CompileDiagnostic}from'./profile-compilation';
  import { ProfilePortBrowser } from './profile-port-browser';
  let { document, assignments, inventory, inventoryClient, selectedId = $bindable(''), companionAuthoring = false, readOnly = false, fitOnMount = false, change, openGameSettings, inspector, selectProviderPort, removeProviderPort, connectBlocks, connectionFrom, connectionTo, highlightedEdges = [], diagnostics = [], undo, redo }: {
    document: DeepReadonly<ProfileDocument>; assignments: readonly DeepReadonly<ProfileLocalAssignment>[]; inventory: readonly DeepReadonly<ResourceSummary>[];
    inventoryClient: Pick<ProfileInventoryClient, 'inspect'>; selectedId?: string; companionAuthoring?:boolean; readOnly?: boolean; fitOnMount?: boolean;
    change: (document: ProfileDocument) => void; openGameSettings?: (gameId: GameId, returnState?: unknown) => void;
    inspector?:Snippet<[CanvasNode]>; selectProviderPort?:(nodeId:string,port:DeepReadonly<ObservedResourcePort>)=>void; removeProviderPort?:(nodeId:string,portId:string)=>void;
    connectBlocks?:(fromNodeId:string,toNodeId:string)=>void;connectionFrom?:(nodeId:string)=>void;connectionTo?:(nodeId:string)=>void;highlightedEdges?:readonly string[];undo?:()=>void;redo?:()=>void;
    diagnostics?:readonly DeepReadonly<CompileDiagnostic>[];
  } = $props();
  let stage: HTMLDivElement;
  let search = $state('');
  let view = $state<CanvasViewport>({ ...untrack(() => document.editor.viewport) });
  let dragged = $state<{id:string;position:CanvasPoint}|null>(null);
  let wire=$state<{nodeId:string;pointer:number;end:CanvasPoint}|null>(null);
  let page = $state<DeepReadonly<ResourceDetails>|null>(null), portsBusy = $state(false), portError = $state('');
  let group = $state<'output'|'input'>('output');
  let drag: { id?: string; origin: CanvasPoint; start: CanvasPoint; viewport: CanvasViewport; pointer: number } | null = null;
  const browser = new ProfilePortBrowser(untrack(() => inventoryClient));
  const nodes = $derived(canvasNodes(document, assignments, inventory));
  const renderedNodes = $derived(nodes.map(node => node.id === dragged?.id ? { ...node, position: dragged.position } : node));
  const selected = $derived(nodes.find(node => node.id === selectedId));
  const selectedDiagnostics=$derived(diagnostics.filter(diagnostic=>diagnostic.location.nodeId===selectedId||diagnostic.location.resourceId===selectedId||document.bindings.some(binding=>diagnostic.location.edgeIds.includes(binding.id)&&(binding.from.nodeId===selectedId||binding.to.nodeId===selectedId))));
  const matches = $derived(canvasSearch(nodes, search));
  const inputs = $derived(selected?.resource?.ports.filter(port=>port.direction==='input') ?? selected?.processing?.inputs ?? selected?.virtual?.ports ?? []);
  const outputs = $derived(selected?.resource?.ports.filter(port=>port.direction==='output') ?? selected?.processing?.outputs ?? []);
  const gameId = $derived(selected ? canvasGameId(selected) : null);
  const observedId = $derived(selected?.observation ? selected.assignment?.sourceId : undefined);
  let portEpoch = 0;
  $effect(() => { view = { ...document.editor.viewport }; });
  $effect(() => {
    const resourceId = companionAuthoring&&selected?.resource?.kind==='companion'?undefined:observedId;
    portEpoch++; browser.clear(); page = null; portError = ''; portsBusy = false;
    if (resourceId) void loadPorts('open',resourceId);
  });
  onMount(() => { if (fitOnMount) fit(); });
  onDestroy(() => { portEpoch++; browser.clear(); });
  function persist(nextView = view) { if (!readOnly) { const next = JSON.parse(JSON.stringify(document)) as ProfileDocument; next.editor.viewport = { ...nextView }; change(next); } }
  function fit() { view = canvasFit(nodes,stage?.clientWidth || 900,stage?.clientHeight || 600); persist(); }
  function zoom(factor:number,at?:CanvasPoint) { view=canvasZoom(view,factor,at??{x:(stage?.clientWidth||900)/2,y:(stage?.clientHeight||600)/2});persist(); }
  function layout() { if(readOnly)return;const next=JSON.parse(JSON.stringify(document)) as ProfileDocument;next.editor.positions=profileAutoLayout(nodes.map(node=>node.id));change(next); }
  function choose(id:string,direction:'input'|'output'='output') { selectedId=id;group=direction; }
  function focusMatch() { const node=matches[0];if(!node)return;choose(node.id);view={...view,x:(stage?.clientWidth||900)/2-(node.position.x+PROFILE_BLOCK_WIDTH/2)*view.zoom,y:(stage?.clientHeight||600)/2-(node.position.y+PROFILE_BLOCK_HEIGHT/2)*view.zoom};persist(); }
  function begin(event:PointerEvent,id?:string) {
    if(event.button!==0)return;
    if(!id && (event.target as Element).closest('button,input,select,a'))return;
    if(id){choose(id);event.stopPropagation();if(readOnly)return;}
    event.preventDefault();stage.setPointerCapture(event.pointerId);
    drag={id,origin:id?{...nodes.find(node=>node.id===id)!.position}:{x:0,y:0},start:{x:event.clientX,y:event.clientY},viewport:{...view},pointer:event.pointerId};
  }
  function beginWire(event:PointerEvent,nodeId:string){if(readOnly||!connectBlocks||event.button!==0)return;event.stopPropagation();event.preventDefault();choose(nodeId,'output');const node=nodes.find(node=>node.id===nodeId)!;wire={nodeId,pointer:event.pointerId,end:{x:node.position.x+PROFILE_BLOCK_WIDTH,y:node.position.y+116}};stage.setPointerCapture(event.pointerId);}
  function move(event:PointerEvent) {if(wire&&event.pointerId===wire.pointer){const rect=stage.getBoundingClientRect();wire={...wire,end:{x:(event.clientX-rect.left-view.x)/view.zoom,y:(event.clientY-rect.top-view.y)/view.zoom}};return;} if(!drag||event.pointerId!==drag.pointer)return;const delta={x:event.clientX-drag.start.x,y:event.clientY-drag.start.y};if(drag.id)dragged={id:drag.id,position:{x:drag.origin.x+delta.x/view.zoom,y:drag.origin.y+delta.y/view.zoom}};else view=canvasPan(drag.viewport,delta); }
  function finish(event:PointerEvent,cancel=false) {if(wire&&event.pointerId===wire.pointer){const from=wire.nodeId;wire=null;if(!cancel){const target=window.document.elementFromPoint(event.clientX,event.clientY)?.closest<HTMLElement>('[data-connection-target]')?.dataset.connectionTarget;if(target&&target!==from)connectBlocks?.(from,target);else connectionFrom?.(from);}if(stage.hasPointerCapture(event.pointerId))stage.releasePointerCapture(event.pointerId);return;} if(!drag||event.pointerId!==drag.pointer)return;if(!cancel){if(dragged&&!readOnly)change(canvasMove(document,dragged.id,dragged.position));else if(!drag.id)persist();}else view={...drag.viewport};drag=null;dragged=null;if(stage.hasPointerCapture(event.pointerId))stage.releasePointerCapture(event.pointerId); }
  function wheel(event:WheelEvent) { event.preventDefault();if(event.ctrlKey||event.metaKey){const rect=stage.getBoundingClientRect();zoom(event.deltaY<0?1.1:1/1.1,{x:event.clientX-rect.left,y:event.clientY-rect.top});}else{view=canvasPan(view,{x:-event.deltaX,y:-event.deltaY});persist();} }
  function keyboard(event:KeyboardEvent) {
    if(event.key==='Escape'&&wire){event.preventDefault();const pointer=wire.pointer;wire=null;if(stage.hasPointerCapture(pointer))stage.releasePointerCapture(pointer);return;}
    if((event.target as Element).closest('input,textarea,select,[contenteditable="true"]'))return;
    if(!readOnly&&(undo||redo)&&(event.ctrlKey||event.metaKey)&&['z','y'].includes(event.key.toLowerCase())){event.preventDefault();if(event.shiftKey||event.key.toLowerCase()==='y')redo?.();else undo?.();return;}
    if((event.target as Element).closest('button,a'))return;
    if(event.key==='+'||event.key==='='){event.preventDefault();zoom(1.2);}else if(event.key==='-'){event.preventDefault();zoom(1/1.2);}else if(event.key==='0'){event.preventDefault();fit();}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();view=canvasPan(view,{x:event.key==='ArrowLeft'?40:event.key==='ArrowRight'?-40:0,y:event.key==='ArrowUp'?40:event.key==='ArrowDown'?-40:0});persist();}
  }
  function lostPointer(event:PointerEvent){if(wire?.pointer===event.pointerId)wire=null;if(drag?.pointer===event.pointerId){view={...drag.viewport};drag=null;dragged=null;}}
  function moveBlock(event:KeyboardEvent,id:string) { if(!event.altKey||readOnly||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key))return;event.preventDefault();event.stopPropagation();const node=nodes.find(node=>node.id===id)!;const step=event.shiftKey?64:16;change(canvasMove(document,id,{x:node.position.x+(event.key==='ArrowLeft'?-step:event.key==='ArrowRight'?step:0),y:node.position.y+(event.key==='ArrowUp'?-step:event.key==='ArrowDown'?step:0)})); }
  async function loadPorts(operation:'open'|'next'|'previous',resourceId?:string) {
    const epoch=portEpoch;portsBusy=true;portError='';
    try{const result=operation==='open'?await browser.open(resourceId!):operation==='next'?await browser.next():await browser.previous();if(epoch===portEpoch&&result)page=result;}
    catch(error){if(epoch===portEpoch)portError=error instanceof Error?error.message:String(error);}
    finally{if(epoch===portEpoch)portsBusy=false;}
  }
</script>

<section class="profile-graph" aria-label="Profile resource graph">
  <div class="canvas-toolbar"><label class="canvas-search"><Icon name="search" size={14}/><input aria-label="Search profile blocks" placeholder="Find a block, type or transport…" bind:value={search} onkeydown={event=>{if(event.key==='Enter')focusMatch();}}/></label><button class="text-button" onclick={focusMatch} disabled={!matches.length}>{search?`${matches.length} matches`:`${nodes.length} blocks`}</button><button class="secondary-button" onclick={fit}>Fit all</button><button class="secondary-button" disabled={readOnly} onclick={layout}>Auto-layout</button><div class="zoom-controls"><button aria-label="Zoom out" onclick={()=>zoom(1/1.2)}>−</button><output aria-label="Canvas zoom">{Math.round(view.zoom*100)}%</output><button aria-label="Zoom in" onclick={()=>zoom(1.2)}>+</button></div></div>
  <p class="canvas-help" id="profile-canvas-help">Drag the background to pan. Ctrl/⌘ + wheel zooms. Select a block to inspect ports; Alt + arrow keys move its focused heading.{#if connectBlocks} Drag Outputs onto Inputs / actions to choose an exact mapping. Ctrl/⌘ + Z undoes; Shift + Z redoes.{/if} Every solid line is an explicit signal route.</p>
  <div class="canvas-layout">
    <!-- svelte-ignore a11y_no_noninteractive_tabindex, a11y_no_noninteractive_element_interactions (The canvas is a keyboard pan/zoom application with instructions.) -->
    <div class="canvas-stage" role="application" aria-label="Profile canvas" aria-describedby="profile-canvas-help" tabindex="0" bind:this={stage} onpointerdown={event=>begin(event)} onpointermove={move} onpointerup={event=>finish(event)} onpointercancel={event=>finish(event,true)} onlostpointercapture={lostPointer} onwheel={wheel} onkeydown={keyboard}>
      <div class="canvas-world" style={`transform:translate(${view.x}px,${view.y}px) scale(${view.zoom})`}>
        <svg class="signal-edges" width="1" height="1" aria-label="Saved signal routes"><defs><marker id="profile-signal-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" /></marker></defs>{#each document.bindings as binding (binding.id)}{@const from=renderedNodes.find(node=>node.id===binding.from.nodeId)}{@const to=renderedNodes.find(node=>node.id===binding.to.nodeId)}{#if from&&to}<path class="signal-edge" class:highlighted={highlightedEdges.includes(binding.id)} class:problem={diagnostics.some(diagnostic=>diagnostic.location.edgeIds.includes(binding.id))} marker-end="url(#profile-signal-arrow)" d={`M${from.position.x+PROFILE_BLOCK_WIDTH},${from.position.y+116} C${from.position.x+PROFILE_BLOCK_WIDTH+64},${from.position.y+116} ${to.position.x-64},${to.position.y+116} ${to.position.x},${to.position.y+116}`}><title>{binding.id}: {binding.from.portId} → {binding.to.portId}</title></path>{/if}{/each}{#if wire}{@const pending=wire}{@const from=renderedNodes.find(node=>node.id===pending.nodeId)}{#if from}<path class="pending-wire" d={`M${from.position.x+PROFILE_BLOCK_WIDTH},${from.position.y+116} L${pending.end.x},${pending.end.y}`}><title>Choose destination, then exact ports</title></path>{/if}{/if}</svg>
        {#each renderedNodes as node (node.id)}
          <article class={['resource-block',node.kind,{selected:node.id===selectedId,dimmed:!!search&&!matches.some(match=>match.id===node.id)}]} style={`left:${node.position.x}px;top:${node.position.y}px;width:${PROFILE_BLOCK_WIDTH}px;height:${PROFILE_BLOCK_HEIGHT}px`} aria-label={`${node.name} · ${node.category}`}>
            <button class="block-heading" aria-pressed={node.id===selectedId} onclick={()=>choose(node.id)} onpointerdown={event=>begin(event,node.id)} onkeydown={event=>moveBlock(event,node.id)}><span class="block-category">{node.category}</span><strong>{node.name}</strong><code>{node.id}</code></button>
            <div class="block-body"><span class="block-state">{canvasStatus(node)}</span><div class="transport-badges">{#each canvasTransports(node) as transport (transport)}<span>{transport}</span>{/each}{#if node.kind==='processing'}<span>{node.processing?.operation.kind}</span>{:else if node.kind==='virtual'}<span>{node.virtual?.layout.buttons.length} buttons · {node.virtual?.layout.axes.length} axes · {node.virtual?.layout.hats.length} hats</span>{/if}</div>{#if node.resource?.kind==='game'}<p class="block-note">Waits for its matching verified game and active profile.</p>{:else if node.observation?.diagnostics.length}<p class="block-note">{node.observation.diagnostics[0]}</p>{:else}<p class="block-note">{node.resource?.required?'Required resource':'Optional resource'}{#if node.observation} · {node.observation.portCount} advertised ports{/if}</p>{/if}</div>
            {#if node.processing}<p class="operation-summary">{processingSummary(node.processing)}</p>{/if}
            <div class="block-port-groups"><button onpointerdown={event=>beginWire(event,node.id)} onclick={()=>{choose(node.id,'output');if(!readOnly)connectionFrom?.(node.id);}}>Outputs <span>{node.resource?.ports.filter(p=>p.direction==='output').length??node.processing?.outputs.length??0}</span></button><button data-connection-target={node.id} onclick={()=>{choose(node.id,'input');if(!readOnly)connectionTo?.(node.id);}}>Inputs / actions <span>{node.resource?.ports.filter(p=>p.direction==='input').length??node.processing?.inputs.length??node.virtual?.ports.length??0}</span></button></div>
          </article>
        {/each}
      </div>
      {#if !nodes.length}<div class="empty-canvas">No resource blocks in this profile. Add resources from inventory.</div>{/if}
    </div>
    <aside class="canvas-inspector" aria-label="Selected block inspector">
      {#if selected}
        <p class="inspector-category">{selected.category}</p><h3>{selected.name}</h3><p class="inspector-state">{canvasStatus(selected)}</p>
        {#if selected.resource}<p class="inspector-note">{selected.resource.required?'Required':'Optional'} resource. Its saved identity and routes remain when disconnected.</p>{/if}
        {#if gameId&&openGameSettings}<button class="text-button game-settings-link" onclick={()=>openGameSettings?.(gameId!,{profileId:document.id,resourceId:selected.id})}>Open game settings <Icon name="arrow" size={12}/></button>{/if}
        {#if selectedDiagnostics.length}<ul class="block-diagnostics" aria-label="Native preflight diagnostics">{#each selectedDiagnostics as diagnostic,index (index)}<li><strong>{diagnostic.code}</strong>: {diagnostic.message}</li>{/each}</ul>{/if}{#if selected.observation?.diagnostics.length}<ul class="block-diagnostics">{#each selected.observation.diagnostics as diagnostic,index (index)}<li>{diagnostic}</li>{/each}</ul>{/if}
        <details open><summary>Selected graph ports · {inputs.length+outputs.length}</summary><p class="inspector-note">Only these exact contracts are saved in the portable graph.</p>{#each ['output','input'] as direction (direction)}<details open={group===direction}><summary>{direction==='output'?'Source outputs':'Destination inputs / actions'} ({direction==='output'?outputs.length:inputs.length})</summary>{#each direction==='output'?outputs:inputs as port (port.id)}<div class="port-row"><strong>{port.name}</strong><code>{port.id}</code><p>{portContractLabel(port.contract)}</p>{#if selected.resource&&removeProviderPort}<button class="text-button" disabled={readOnly} onclick={()=>removeProviderPort?.(selected!.id,port.id)}>Remove port and its routes</button>{/if}</div>{:else}<p class="inspector-note">No {direction} ports selected. Browse the provider catalogue below.</p>{/each}</details>{/each}</details>
        {#if selected.observation&&selected.assignment}
          {#if !companionAuthoring||selected.resource?.kind!=='companion'}<details open><summary>Provider catalogue · {selected.observation.portCount} advertised</summary><p class="inspector-note">Browse without changing routes or graph ports. Large catalogues stay paged.</p><button class="text-button" disabled={portsBusy} onclick={()=>loadPorts('open',selected!.assignment!.sourceId)}>Refresh ports</button>{#if portError}<p class="port-error" role="status">{portError}</p>{/if}{#if portsBusy}<p class="inspector-note" role="status">Loading port page…</p>{/if}{#if page}<p class="port-page-count">{page.total?`${page.offset+1}–${page.offset+page.ports.length}`:'0'} of {page.total} cached port contracts</p>{#each ['output','input'] as direction (direction)}<details open><summary>{direction==='output'?'Source outputs / telemetry':'Destination inputs / actions'} on this page ({page.ports.filter(port=>port.descriptor.direction===direction).length})</summary>{#each page.ports.filter(port=>port.descriptor.direction===direction) as port (`${port.descriptor.id}/${port.contractHash}`)}<div class="port-row"><strong>{port.descriptor.name}</strong><code>{port.descriptor.id}</code><p>{portContractLabel(port.descriptor.contract)}</p><small>{port.current?'Current capability':'Cached / unavailable capability'}</small>{#if selectProviderPort}<button class="secondary-button" disabled={readOnly||selected.assignment.ports.some(pin=>pin.observedPortId===port.descriptor.id&&pin.expectedContractHash===port.contractHash)} onclick={()=>selectProviderPort?.(selected!.id,port)}>{selected.assignment.ports.some(pin=>pin.observedPortId===port.descriptor.id&&pin.expectedContractHash===port.contractHash)?'Selected in graph':'Use this exact port'}</button>{/if}</div>{:else}<p class="inspector-note">None on this page.</p>{/each}</details>{/each}<div class="port-pagination"><button class="secondary-button" disabled={portsBusy||!browser.hasPrevious} onclick={()=>loadPorts('previous')}>Previous</button><button class="secondary-button" disabled={portsBusy||!browser.hasNext} onclick={()=>loadPorts('next')}>Next page</button></div>{/if}</details>
          {/if}<details><summary>Connection metadata ({selected.observation.connections.length})</summary><p class="inspector-note">Transport information describes the resource; it is never a canvas wire.</p>{#each selected.observation.connections as connection (`${connection.scope}/${connection.key}/${connection.route.id}`)}<div class="connection-row"><strong>{connection.route.transport.toUpperCase()}</strong><p>{connection.route.baselineReady?'Fresh baseline available':'Waiting for a fresh baseline'} · {connection.route.writable?'Write capability advertised':'No write capability advertised'}</p><dl>{#each Object.entries(connection.route.attributes) as [key,value] (key)}<div><dt>{key}</dt><dd>{value}</dd></div>{/each}</dl></div>{/each}<dl>{#each Object.entries(selected.observation.attributes) as [key,value] (key)}<div><dt>{key}</dt><dd>{value}</dd></div>{/each}</dl></details>
        {:else if selected.resource}<p class="inspector-note">{selected.assignment?'This saved resource is currently absent from inventory. Its block, exact ports and routes remain intact.':'Select a matching resource from inventory before using this copied block.'}</p>{/if}
        {#if inspector}{@render inspector(selected)}{/if}
      {:else}<div class="inspector-empty"><Icon name="network" size={28}/><h3>Select a block</h3><p>Inspect source outputs, destination actions and transport attributes. Browsing sends no device commands.</p></div>{/if}
    </aside>
  </div>
  <div class="graph-result-summary"><span>{document.resources.length} resource blocks</span><span>{document.bindings.length} signal routes</span><span>{document.processingNodes.length} transformations</span><span>{document.virtualOutputs.length} requested virtual controllers</span><span>{document.visibility.filter(intent=>intent.mode==='hidden-while-active').length} hide-while-active requests</span></div>
</section>

<style>
  .operation-summary{font-size:9px;line-height:1.5;color:var(--soft);margin:0;padding:0 14px 9px;display:-webkit-box;-webkit-line-clamp:2;line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.signal-edge.problem{stroke:#d3a078;stroke-width:3}.signal-edge.highlighted{stroke:#e0bd7e;stroke-width:4}.pending-wire{fill:none;stroke:var(--accent);stroke-width:2;stroke-dasharray:5 4}.port-row button{font-size:9px;display:block;margin-top:9px}
  .profile-graph{border:1px solid var(--line);border-radius:9px;overflow:hidden;background:var(--surface);}.canvas-toolbar{display:flex;align-items:center;gap:10px;padding:14px;flex-wrap:wrap;border-bottom:1px solid var(--line);}.canvas-search{display:flex;align-items:center;gap:8px;flex:1;min-width:190px;max-width:350px;color:var(--muted);}.canvas-search input{background:transparent;border:0;color:var(--text);font-size:11px;min-width:0;width:100%;outline:0;}.canvas-search:focus-within{outline:1px solid var(--accent);outline-offset:6px;border-radius:2px;}.canvas-toolbar button{font-size:10px;}.zoom-controls{display:flex;align-items:center;border:1px solid var(--line);border-radius:6px;margin-left:auto;}.zoom-controls button{width:30px;height:30px;background:transparent;color:var(--soft);font-size:16px;}.zoom-controls output{min-width:44px;text-align:center;font-size:10px;color:var(--muted);}.canvas-help{font-size:9px;color:var(--muted);line-height:1.7;padding:10px 14px;margin:0;border-bottom:1px solid var(--line);}.canvas-layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;}.canvas-stage{position:relative;min-height:620px;height:70vh;max-height:850px;overflow:hidden;touch-action:none;background-color:var(--bg);background-image:radial-gradient(var(--line) 1px,transparent 1px);background-size:20px 20px;}.canvas-stage:focus-visible{outline:2px solid var(--accent);outline-offset:-3px;}.canvas-world{position:absolute;left:0;top:0;transform-origin:0 0;}.signal-edges{position:absolute;overflow:visible;pointer-events:none;}.signal-edge{fill:none;stroke:var(--accent);stroke-width:2;}.signal-edges marker path{fill:var(--accent);}.resource-block{position:absolute;border:1px solid var(--line);border-radius:9px;background:var(--surface);box-shadow:0 8px 24px #0002;overflow:hidden;display:flex;flex-direction:column;transition:opacity .12s;}.resource-block.selected{outline:2px solid var(--accent);outline-offset:2px;}.resource-block.processing{border-color:#b794d2;}.resou